import React, { useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';

const ATS_P4 = () => {
  const context = useOutletContext();
  
  // 1. Remove useState for displayData. 
  // Read directly from context so it's always "live".
  const resumeData = context?.ats?.data;

  // 2. Keep the log to confirm data is arriving
 useEffect(() => {
    console.log("--- P4 DEBUG START ---");
    console.log("Full Context Object:", context);
    console.log("Context ATS object:", context?.ats);
    console.log("Data inside ATS:", context?.ats?.data);
    console.log("--- P4 DEBUG END ---");
  }, [context]);

  // 3. Fallback logic: If resumeData is null, show the message
  if (!resumeData) {
    return <div className="summary-box">Waiting for data stream...</div>;
  }

  // 4. If data exists, render it. It will automatically update 
  // as soon as resumeData changes in MainLayout.
  return (
    <div className="summary-box">
      <h3>Persistence & System Telemetry</h3>
      <div className="telemetry-log p-4 bg-black text-green-400 font-mono text-sm rounded">
        <p>{'>'} System Initialized...</p>
        <p>{'>'} Sync Status: {resumeData.db_synced ? "COMMITTED" : "PENDING"}</p>
        <p>{'>'} Vector Index: {resumeData.vector_id || "NOT_INDEXED"}</p>
        <p>{'>'} Total Ops Time: {resumeData.processing_time || 0}ms</p>
      </div>
    </div>
  );
};
export default ATS_P4;
